
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_k_tkvln_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_k_tkvln", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([1.157047097237526e+02, 1.120082470602776e+02, 1.069497064076352e+02, 1.001762063022660e+02, 9.138443202264908e+01, 8.046822065014646e+01, 6.773712617339854e+01, 5.411798027484788e+01, 4.104692503169102e+01, 2.928309585126037e+01, 1.564756537644925e+01, 3.547593017957110e+00, 2.222945135129193e+00, 1.827206126131433e+00, 1.338463089536623e+00, 9.605931060017161e-01, 7.576844007087558e-01, 6.563550668107357e-01, 6.033059770695784e-01, 5.847339052202347e-01]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


